
WITH params AS (SELECT array('ID-000379','IN-277727') AS crews),
sac_dedup AS (
  SELECT *, ROW_NUMBER() OVER (
    PARTITION BY CREW_CODE, CAST(SIGN_ON_DATE AS DATE), CAST(SIGN_OFF_DATE AS DATE), VESSEL_NAME
    ORDER BY CAST(CONTRACT_START_DATE AS TIMESTAMP), POSITION_NAME, CAST(FROM_DATE AS TIMESTAMP)
  ) rn
  FROM reporting_layer.sac_prod_seafarer_public.revised_base_view
  WHERE CREW_CODE IN (SELECT explode(crews) FROM params)
),
smac_dedup AS (
  SELECT *, ROW_NUMBER() OVER (
    PARTITION BY CREW_CODE, CAST(SIGN_ON_DATE AS DATE), CAST(SIGN_OFF_DATE AS DATE), VESSEL_NAME
    ORDER BY CAST(CONTRACT_START_DATE AS TIMESTAMP), POSITION_NAME, CAST(FROM_DATE AS TIMESTAMP)
  ) rn
  FROM reporting_layer.smac_prod.revised_base_view
  WHERE CREW_CODE IN (SELECT explode(crews) FROM params)
)
SELECT column_name, matches, mismatches, total,
  ROUND(100.0 * matches / total, 2) AS match_pct
FROM (
  SELECT 'SEAFARER_ID' AS column_name, SUM(CASE WHEN COALESCE(CAST(s.SEAFARER_ID AS STRING),'')=COALESCE(CAST(m.SEAFARER_ID AS STRING),'') THEN 1 ELSE 0 END) AS matches, SUM(CASE WHEN COALESCE(CAST(s.SEAFARER_ID AS STRING),'')<>COALESCE(CAST(m.SEAFARER_ID AS STRING),'') THEN 1 ELSE 0 END) AS mismatches, COUNT(*) AS total FROM sac_dedup s INNER JOIN smac_dedup m 
    ON s.CREW_CODE = m.CREW_CODE
   AND CAST(s.SIGN_ON_DATE AS DATE) = CAST(m.SIGN_ON_DATE AS DATE)
   AND CAST(s.SIGN_OFF_DATE AS DATE) <=> CAST(m.SIGN_OFF_DATE AS DATE)
   AND s.VESSEL_NAME <=> m.VESSEL_NAME
   AND s.rn = m.rn
 UNION ALL SELECT 'FIRST_NAME' AS column_name, SUM(CASE WHEN COALESCE(CAST(s.FIRST_NAME AS STRING),'')=COALESCE(CAST(m.FIRST_NAME AS STRING),'') THEN 1 ELSE 0 END) AS matches, SUM(CASE WHEN COALESCE(CAST(s.FIRST_NAME AS STRING),'')<>COALESCE(CAST(m.FIRST_NAME AS STRING),'') THEN 1 ELSE 0 END) AS mismatches, COUNT(*) AS total FROM sac_dedup s INNER JOIN smac_dedup m 
    ON s.CREW_CODE = m.CREW_CODE
   AND CAST(s.SIGN_ON_DATE AS DATE) = CAST(m.SIGN_ON_DATE AS DATE)
   AND CAST(s.SIGN_OFF_DATE AS DATE) <=> CAST(m.SIGN_OFF_DATE AS DATE)
   AND s.VESSEL_NAME <=> m.VESSEL_NAME
   AND s.rn = m.rn
